            workSheet.Cells[1, 7].Value = "Complaint Against";
            workSheet.Cells[1, 8].Value = "Registration Number";
            workSheet.Cells[1, 9].Value = "Name of Real Estate Project/ Agent";
            workSheet.Cells[1, 10].Value = "Entrusted To (Bench Name)";
            workSheet.Cells[1, 11].Value = "Status";
            workSheet.Cells[1, 12].Value = "Status Date";
            workSheet.Cells[1, 13].Value = "Remarks, if Any";

            //Body of table  
            int recordIndex = 2;
            foreach (var QRcodeItem in objXlslist)
            {
                workSheet.Cells[recordIndex, 1].Value = (recordIndex - 1).ToString();
                workSheet.Cells[recordIndex, 2].Value = QRcodeItem.ComplaintRegDiaryNumber_Name;
                workSheet.Cells[recordIndex, 3].Value = QRcodeItem.CreatedOn.HasValue ? QRcodeItem.CreatedOn.Value.ToString("dd-MMM-yyyy") : string.Empty;
