                workSheet.Cells[recordIndex, 5].Value = QRcodeItem.Complainant_MobileNumber;
                workSheet.Cells[recordIndex, 6].Value = QRcodeItem.Respondent_Name;
                workSheet.Cells[recordIndex, 7].Value = QRcodeItem.RelatesComplaint_ComplaintAgainstType;
                workSheet.Cells[recordIndex, 8].Value = QRcodeItem.A_column;
                workSheet.Cells[recordIndex, 9].Value = QRcodeItem.B_column;
                workSheet.Cells[recordIndex, 10].Value = QRcodeItem.C_column;
                workSheet.Cells[recordIndex, 11].Value = QRcodeItem.EventAction_Aggregate;
                workSheet.Cells[recordIndex, 12].Value = QRcodeItem.EventAction_IdentifiedOn.HasValue ? QRcodeItem.EventAction_IdentifiedOn.Value.ToString("dd-MMM-yyyy") : string.Empty;
                workSheet.Cells[recordIndex, 13].Value = string.Empty;

