        #region Display Form-Execution Complainant and Respondent

        [HttpGet]
        public ActionResult Display_FormExeaddmoreComplainant()
        {

            string userRole = string.Empty;
            Int64 ComplaintFormID = 0;
            userRole = getUserRole();
            if (Session["zapFormExeDiaryNumber"] != null)
            {
                Int64? ComplaintForm_ID = Convert.ToInt64(Session["zapComplaintFormExe_ID"]);
                ComplaintFormID = (ComplaintForm_ID != null) ? Convert.ToInt64(ComplaintForm_ID) : 0;
            }


            ClsPrp_AuthorityDeskFormExe_Addmore_Complainant aa = new ClsPrp_AuthorityDeskFormExe_Addmore_Complainant();
            ClsMethod_AuthDesk_FormMN_Addmore_Complainant sdb = new ClsMethod_AuthDesk_FormMN_Addmore_Complainant();

            aa.FormExe_Complainant = sdb.Display_ComplainantFormExe_Detail(ComplaintFormID);

            #region Lock - Unlock (Logic Display Message)
            bool var_Anydocopen = false;
            bool var_Alldocclosed = false;
            bool var_Anydocpermanent = false;

            if (aa.FormExe_Complainant.Count == 0)
            {
                aa.IsDraftAllComplainants = 0;
            }

            foreach (var item in aa.FormExe_Complainant)
            {
                if (item.IsDraft == 1)
                {
                    var_Alldocclosed = true;
                }
                if (item.IsDraft == 5)
                {
                    var_Anydocopen = true;
                }
                if (item.IsDraft == 6)
                {
                    var_Anydocpermanent = true;
                }
            }

            if (var_Anydocpermanent)
            {
                aa.IsDraftAllComplainants = 6;
            }
            else if (var_Anydocopen)
            {
                aa.IsDraftAllComplainants = 5;
            }
            else if (var_Alldocclosed)
            {
                aa.IsDraftAllComplainants = 1;
            }
            else
            {
                aa.IsDraftAllComplainants = 0;
            }
            #endregion

            if (aa.FormExe_Complainant.Count >= 1)
            {
                foreach (var item in aa.FormExe_Complainant)
                {
                    aa.AdditionComplainant_IndexID = item.AdditionComplainant_IndexID;
                    aa.AdditionComplainant_ID = item.AdditionComplainant_ID;
                    aa.ComplainantApplicant_RelatedComplaint_ID = item.ComplainantApplicant_RelatedComplaint_ID;
                    aa.ComplainantorApplicant_RelatedComplaint_Code = item.ComplainantorApplicant_RelatedComplaint_Code;
                    aa.Profile_ID = item.Profile_ID;
                    aa.User_ID = item.User_ID;
                    aa.ComplaintType_Exe = item.ComplaintType_Exe;

                    aa.Name_of_Complainant_or_Applicant = item.Name_of_Complainant_or_Applicant;
                    aa.EmailAddress = item.EmailAddress;
                    aa.MobileNumber = item.MobileNumber;
                    aa.LandlineNumber = item.LandlineNumber;
                    aa.Complainant_AadhaarNumber = item.Complainant_AadhaarNumber;
                    aa.RegOffice_AddressLine1 = item.RegOffice_AddressLine1;
                    aa.RegOffice_AddressLine2 = item.RegOffice_AddressLine2;
                    aa.RegOffice_AddressStateCode = item.RegOffice_AddressStateCode;
                    aa.RegOffice_AddressDistrictCode = item.RegOffice_AddressDistrictCode;
                    aa.RegOffice_AddressPIN = item.RegOffice_AddressPIN;
                    aa.IsSameCommunicationAdd_ResOffAdd = item.IsSameCommunicationAdd_ResOffAdd;
                    aa.Service_AddressLine1 = item.Service_AddressLine1;
                    aa.Service_AddressLine2 = item.Service_AddressLine2;
                    aa.Service_AddressStateCode = item.Service_AddressStateCode;
                    aa.Service_AddressDistrictCode = item.Service_AddressDistrictCode;
                    aa.Service_AddressPIN = item.Service_AddressPIN;
                    aa.Remarks_IfAny = item.Remarks_IfAny;
                    aa.A_column = item.A_column;
                    aa.B_column = item.B_column;
                    aa.C_column = item.C_column;

                    aa.IsActive = item.IsActive;
                    aa.IsDraft = item.IsDraft;
                    aa.IsLock = item.IsLock;
                    aa.IsPublicView = item.IsPublicView;
                }
            }

            if (Session["zapFormExeDiaryNumber"] != null)
            {
                string FormExeDiaryNumber = Session["zapFormExeDiaryNumber"].ToString();
                string FormExeComplainantName = Session["zapFormExeComplainantName"].ToString();
                string FormExeRespondantName = Session["zapFormExeRespondantName"].ToString();
                string ComplainantRERAnumber = Session["zapComplainantRERAnumber"].ToString();
                Int64? ComplaintFormExe_ID = Convert.ToInt64(Session["zapComplaintFormExe_ID"]);
                DateTime? LastModifiedOn = Convert.ToDateTime(Session["LastModifiedOn"]);

                aa.zapRelated_Complaint_ID = (ComplaintFormExe_ID != null) ? Convert.ToInt64(ComplaintFormExe_ID) : 0;
                aa.zapRelated_RegDiaryNumber = (String.IsNullOrEmpty(FormExeDiaryNumber) ? "" : FormExeDiaryNumber);
                aa.zapComplainantRERAnumber = (String.IsNullOrEmpty(ComplainantRERAnumber) ? "" : ComplainantRERAnumber);
                aa.zapComplainantName = (String.IsNullOrEmpty(FormExeComplainantName) ? "" : FormExeComplainantName);
                aa.zapRespondantName = (String.IsNullOrEmpty(FormExeRespondantName) ? "" : FormExeRespondantName);
                aa.zapComplaintFormLastModifiedOn = LastModifiedOn;
            }
            else
            {
                aa.zapRelated_Complaint_ID = 0;
                aa.zapRelated_RegDiaryNumber = "";
                aa.zapComplainantRERAnumber = "";
                aa.zapComplainantName = "";
                aa.zapRespondantName = "";
            }

            return View("Display_FormExeaddmoreComplainant", aa);
        }

        //Lock-Unlock Handler (FormEXE addmoreComplainant List)
        public JsonResult LockUnlockHandler_FormExeaddmoreComplainantList(string parmComplaintID, string parmLockUnlock, string parmRelatedComplaintID)
        {
            Int32 retvalueLockUnlock = 0;
            Int32 retValue = 1;
            try
            {
                #region Parameters
                Int64 ComplaintCode = 0;
                Int64 RelatedComplaintCode = 0;
                Int32 IsDraftCode = 0;
                string userName = string.Empty;
                string userID = string.Empty;
                string RelatedRemarksIfAny = string.Empty;
                string RelatedLockUnlockMsg = string.Empty;

                if (parmComplaintID != string.Empty)
                {
                    ComplaintCode = Convert.ToInt64(parmComplaintID);
                }
                if (parmLockUnlock != string.Empty)
                {
                    IsDraftCode = Convert.ToInt32(parmLockUnlock);
                }
                if (parmRelatedComplaintID != string.Empty)
                {
                    RelatedComplaintCode = Convert.ToInt32(parmRelatedComplaintID);
                }
                userID = User.Identity.GetUserId();
                userName = User.Identity.GetUserName();
                RelatedRemarksIfAny = "FormExecution additional complainant(s) list details";
                switch (IsDraftCode)
                {
                    case 1:
                        RelatedLockUnlockMsg = "Unlock request";
                        break;
                    case 5:
                        RelatedLockUnlockMsg = "Lock request";
                        break;
                    default:
                        RelatedLockUnlockMsg = "others";
                        break;
                }
                #endregion
                ClsMethod_AuthDesk_FormMN_Addmore_Complainant sdb = new ClsMethod_AuthDesk_FormMN_Addmore_Complainant();
                retvalueLockUnlock = sdb.Update_LockUnLockHandler_FormExeaddmoreComplainantListDetails(ComplaintCode, RelatedComplaintCode, IsDraftCode, userName, userID, RelatedRemarksIfAny, RelatedLockUnlockMsg);
            }
            catch (Exception ex)
            {
                string retex = ex.ToString();
                retValue = 0;
            }

            Int32 IsDraft = retvalueLockUnlock; // 5;            
            Int32 parmStatusCode = 102;
            string parmStatus = "Request processed! Invalid.";
            if (retValue == 1)
            {
                if (IsDraft == 1)
                {
                    parmStatusCode = 101;
                    parmStatus = "Successfully locked additional complainant(s) list details.";
                }
                else if (IsDraft == 5)
                {
                    parmStatusCode = 105;
                    parmStatus = "Successfully un-locked additional complainant(s) list details.";
                }
                else if (IsDraft == 6)
                {
                    parmStatusCode = 106;
                    parmStatus = "Invalid lock-Unlock Action.";
                }
                else
                {
                    parmStatusCode = 100;
                    parmStatus = "Invalid lock-Unlock Action.";
                }
            }
            else
            {
                parmStatusCode = 102;
                parmStatus = "Request processed! Failed.";
            }

            return Json(new
            {
                statusCode = parmStatusCode,
                status = parmStatus,
                remarks = string.Empty
            }, JsonRequestBehavior.AllowGet);
        }

