        [HttpPost]
        public async Task<ActionResult> FormExeInfoEventInsert(ClsPrp_AuthorityDesk_FormExeEventLog smodel)
        {
            //async Task<ActionResult>  ActionResult
            ClsPrp_AuthorityDesk_FormExeEventLog aa = new ClsPrp_AuthorityDesk_FormExeEventLog();
            ClsPrp_AuthorityDesk_FormExe_EventActionSaveAsDraftRemarks objdraftsave = new ClsPrp_AuthorityDesk_FormExe_EventActionSaveAsDraftRemarks();
            try
            {
                if (ModelState.IsValid)
                {
                    ClsMethod_ComplaintFormM_Helpdesk sdb = new ClsMethod_ComplaintFormM_Helpdesk();
                    string pUserRole = string.Empty;
                    pUserRole = getUserRole();
                    string pUser_WhoIdentified = User.Identity.Name;
                    string pUser_WhoIdentifiedCode = User.Identity.GetUserId();

                    Int64 ComplaintID = 0;
                    string FormDiaryNumber = string.Empty;
                    string SourceIP = string.Empty;

                    //99(STOP)-If Other than NoReplyWithin15Days After InComplete Action
                    //1(OK)-If NoReplyWithin15Days Action After InComplete Action
                    //1(OK)-If Apply Any Action After Any Action except InComplete Action
                    Int64 retValue = sdb.Checkfn_ComplaintFormExe_InfoEventDetailsByID(smodel, pUser_WhoIdentified);

                    if (retValue != 99)
                    {
                        if (sdb.Add_ComplaintFormExe_InfoEvent(smodel, pUserRole, pUser_WhoIdentified))
                        {
                            // SaveAsDraft updation method and parameters
                            #region Parameters
                            objdraftsave.ComplaintFormExe_EventActionDraft_ID = 0;
                            objdraftsave.EventAction_Type = smodel.EventAction_Type;
                            objdraftsave.EventAction_IdentifiedBy = pUser_WhoIdentified;
                            objdraftsave.EventAction_IdentifiedOn = DateTime.Now;
                            objdraftsave.Related_ComplaintorApplication_ID = smodel.Related_Complaint_ID;
                            objdraftsave.Related_RegDiaryNumber = smodel.Related_RegDiaryNumber;

                            objdraftsave.IdentifiedBy_UserId = pUser_WhoIdentifiedCode;
                            objdraftsave.IdentifiedBy_RoleId = pUserRole;
                            objdraftsave.IdentifiedBy_FormType = "FormTypeExecution";

                            objdraftsave.EventAction_Summary = string.Empty;
                            objdraftsave.EventAction_Description = string.Empty;
                            objdraftsave.EventAction_Category = string.Empty;
                            objdraftsave.EventAction_Aggregate = string.Empty;
                            objdraftsave.EventAction_Relationship = "SaveAsDraft";
                            objdraftsave.AssignedTo = string.Empty;

                            objdraftsave.Target_ResolutionDate = DateTime.Now;
                            objdraftsave.Target_ResolutionSummary = string.Empty;
                            objdraftsave.Actual_ResolutionDate = DateTime.Now;
                            objdraftsave.ProgressStatus = string.Empty;
                            objdraftsave.Remarks_IfAny = smodel.Remarks_IfAny;

                            objdraftsave.IsActive = 2;
                            objdraftsave.IsDraft = 1;
                            objdraftsave.CreatedBy = pUser_WhoIdentified;
                            objdraftsave.CreatedOn = DateTime.Now;
                            objdraftsave.ModifyBy = pUser_WhoIdentified;
                            objdraftsave.ModifyOn = DateTime.Now;
                            #endregion
                            bool val = sdb.Update_ComplaintFormExe_InfoEventSaveAsDraftRemarks(objdraftsave, pUser_WhoIdentified);

                            // Email Configuration Objects
                            EmailService objEmailConfig = new EmailService();
                            IdentityMessage clsprpEmail = new IdentityMessage();

                            // Pre-Hearing OR Hearing - Notice to Complainant(s)
                            if (smodel.EventAction_Type == 330061 || smodel.EventAction_Type == 330058)
                            {
                                string chkComplainantNoticeRegDNumber = smodel.Related_RegDiaryNumber.ToString();
                                if (string.IsNullOrEmpty(chkComplainantNoticeRegDNumber))
                                {
                                    if (chkComplainantNoticeRegDNumber.Length > 18)
                                    {
                                        //Transfer Case
                                        clsprpEmail = getfunctionSendEmailAsynFormExeTrCaseExe(smodel);
                                    }
                                    else
                                    {
                                        clsprpEmail = getfunctionSendEmailAsynFormExe(smodel);
                                    }
                                }
                                else
                                {
                                    clsprpEmail = getfunctionSendEmailAsynFormExe(smodel);
                                }

                                ComplaintID = smodel.Related_Complaint_ID;
                                FormDiaryNumber = smodel.Related_RegDiaryNumber;
                                SourceIP = getSourceIPaddress(); // Request.UserHostAddress;                            

                                if (clsprpEmail.Destination != string.Empty)
                                {
                                    await objEmailConfig.SendComplaintExeEmailAsync(clsprpEmail, ComplaintID, FormDiaryNumber, SourceIP, pUser_WhoIdentified);
                                }
                            }
                            // Pre-Hearing OR Hearing - Notice to Respondent(s)
                            if (smodel.EventAction_Type == 330059)
                            {
                                string chkRespondentNoticeRegDNumber = smodel.Related_RegDiaryNumber.ToString();
                                if (string.IsNullOrEmpty(chkRespondentNoticeRegDNumber))
                                {
                                    if (chkRespondentNoticeRegDNumber.Length > 18)
                                    {
                                        //Transfer Case
                                        clsprpEmail = getfunctionSendEmailAsynFormExeTrCaseExe(smodel);
                                    }
                                    else
                                    {
                                        clsprpEmail = getfunctionSendEmailAsynRespondentFormExe(smodel);
                                    }
                                }
                                else
                                {
                                    clsprpEmail = getfunctionSendEmailAsynRespondentFormExe(smodel);
                                }

                                ComplaintID = smodel.Related_Complaint_ID;
                                FormDiaryNumber = smodel.Related_RegDiaryNumber;
                                SourceIP = getSourceIPaddress(); //Request.UserHostAddress;

                                if (clsprpEmail.Destination != string.Empty)
                                {
                                    await objEmailConfig.SendComplaintExeEmailAsync(clsprpEmail, ComplaintID, FormDiaryNumber, SourceIP, pUser_WhoIdentified);
                                }
                            }

                            //if (smodel.EventAction_Type == 330061)
                            //{
                            //await UserManager.SendEmailAsync(UID, "RERA, Punjab - NOTICE FOR PRE-HEARING", "<b>Dear " + UserNam + "</b>,<br /><br />Your application for registration of <b>Real Estate Agent</b> with Application ID <b>" + Profile + "</b> has been successfully submitted with the Authority. <br /><br /><br />Kindly submit the hard copy of the application form along with the uploaded documents within 7 days of submission of online application with RERA, Punjab. <br /><br /><br /> <b>Thanks and Regard,<br /> RERA, Punjab</b> <br /><br />Please do not reply to this e-mail, this is a system generated email.");
                            //}

                            ViewBag.Message = "Details Added Successfully";
                            ModelState.Clear();
                            TempData["EventSubmitMessage"] = "Application Performa successfully Submitted.";
                            TempData["EventSubmitMessageSaveAsDraftFlag"] = "1";
                        }
                        else
                        {
                            ViewBag.Message = "Bad Request! Details Failed";
                            ModelState.Clear();
                            TempData["EventSubmitMessage"] = "Bad Request! Invalid Action Details";
                            TempData["EventSubmitMessageSaveAsDraftFlag"] = "2";
                        }
                    }
                    else
                    {
                        ViewBag.Message = "Bad Request! Details Failed";
                        ModelState.Clear();
                        TempData["EventSubmitMessage"] = "Bad Request! Invalid Action Details";
                        TempData["EventSubmitMessageSaveAsDraftFlag"] = "2";
                    }

                    //to bind subCheckList master
                    aa.EventMaster = sdb.Display_AuthorityDesk_ComplaintEvent_Master(pUserRole);

                    if (Session["zapFormExeDiaryNumber"] != null)
                    {
                        string FormExeDiaryNumber = Session["zapFormExeDiaryNumber"].ToString();
                        string FormExeComplainantName = Session["zapFormExeComplainantName"].ToString();
                        string FormExeRespondantName = Session["zapFormExeRespondantName"].ToString();
                        string ComplainantRERAnumber = Session["zapComplainantRERAnumber"].ToString();
                        Int64? ComplaintFormExe_ID = Convert.ToInt64(Session["zapComplaintFormExe_ID"]);
                        DateTime? LastModifiedOn = Convert.ToDateTime(Session["LastModifiedOn"]);

                        aa.Related_Complaint_ID = (ComplaintFormExe_ID != null) ? Convert.ToInt64(ComplaintFormExe_ID) : 0;
                        aa.Related_RegDiaryNumber = (String.IsNullOrEmpty(FormExeDiaryNumber) ? "" : FormExeDiaryNumber);
                        aa.ComplainantRERAnumber = (String.IsNullOrEmpty(ComplainantRERAnumber) ? "" : ComplainantRERAnumber);
                        aa.ComplainantName = (String.IsNullOrEmpty(FormExeComplainantName) ? "" : FormExeComplainantName);
                        aa.RespondantName = (String.IsNullOrEmpty(FormExeRespondantName) ? "" : FormExeRespondantName);
                        aa.ComplaintFormLastModifiedOn = LastModifiedOn;
                    }
                    else
                    {
                        aa.Related_Complaint_ID = 0;
                        aa.Related_RegDiaryNumber = "";
                        aa.ComplainantRERAnumber = "";
                        aa.ComplainantName = "";
                        aa.RespondantName = "";
                    }

                }
                return View("FormExeInfoEventInsert", aa);
            }
            catch (Exception ex)
            {
                string retex = ex.ToString();
                TempData["EventSubmitMessage"] = "Sorry, Application Performa is pending";
                TempData["EventSubmitMessageSaveAsDraftFlag"] = "2";
                return View("FormMInfoEventInsert", aa);
            }
        }

