            userRole = getUserRole();

            if (Session["zapFormNDiaryNumber"] != null)
            {
                Int64? ComplaintFormN_ID = Convert.ToInt64(Session["zapComplaintFormN_ID"]);
                ComplaintFormNID = (ComplaintFormN_ID != null) ? Convert.ToInt64(ComplaintFormN_ID) : 0;
            }
            aa.prpFormN_Docs = sdb.Display_ComplaintFormN_Documents_ByComplaintFormNID_ForDesk(ComplaintFormNID);

            #region Lock - Unlock (Logic Display Message)
            bool var_Anydocopen = false;
            bool var_Alldocclosed = false;
            bool var_Anydocpermanent = false;

            if (aa.prpFormN_Docs.Count == 0)
            {
                aa.IsDraftAllDocuments = 0;
            }

            foreach (var item in aa.prpFormN_Docs)
            {
                aa.ComplainantApplicant_RelatedComplaint_ID = item.ComplainantApplicant_RelatedComplaint_ID;
                aa.ComplainantApplicant_RelatedComplaint_Code = item.ComplainantApplicant_RelatedComplaint_Code;
                aa.ComplaintDoc_InfoCode = item.ComplaintDoc_InfoCode;
                aa.ComplaintDoc_InfoName = item.ComplaintDoc_InfoName;
                aa.ListEnclDocument_IndexID = item.ListEnclDocument_IndexID;
                aa.zapRelated_Complaint_ID = item.zapRelated_Complaint_ID;
                aa.zapRelated_RegDiaryNumber = item.zapRelated_RegDiaryNumber;
                aa.IsActive = item.IsActive;
                aa.IsDraft = item.IsDraft;

                if (item.IsDraft == 1)
                {
                    var_Alldocclosed = true;
                }
                if (item.IsDraft == 5)
                {
                    var_Anydocopen = true;
                }
                if (item.IsDraft == 6)
                {
                    var_Anydocpermanent = true;
                }
            }

            if (var_Anydocpermanent)
            {
                aa.IsDraftAllDocuments = 6;
            }
            else if (var_Anydocopen)
            {
                aa.IsDraftAllDocuments = 5;
            }
            else if (var_Alldocclosed)
            {
                aa.IsDraftAllDocuments = 1;
            }
            else
            {
                aa.IsDraftAllDocuments = 0;
            }
            #endregion

            if (Session["zapFormNDiaryNumber"] != null)
            {
                string FormNDiaryNumber = Session["zapFormNDiaryNumber"].ToString();
                string FormNComplainantName = Session["zapFormNComplainantName"].ToString();
                string FormNRespondantName = Session["zapFormNRespondantName"].ToString();
                string ComplainantRERAnumber = Session["zapComplainantRERAnumber"].ToString();
                Int64? ComplaintFormN_ID = Convert.ToInt64(Session["zapComplaintFormN_ID"]);
                DateTime? LastModifiedOn = Convert.ToDateTime(Session["LastModifiedOn"]);

                aa.zapRelated_Complaint_ID = (ComplaintFormN_ID != null) ? Convert.ToInt64(ComplaintFormN_ID) : 0;
                aa.zapRelated_RegDiaryNumber = (String.IsNullOrEmpty(FormNDiaryNumber) ? "" : FormNDiaryNumber);
                aa.zapComplainantRERAnumber = (String.IsNullOrEmpty(ComplainantRERAnumber) ? "" : ComplainantRERAnumber);
                aa.zapComplainantName = (String.IsNullOrEmpty(FormNComplainantName) ? "" : FormNComplainantName);
                aa.zapRespondantName = (String.IsNullOrEmpty(FormNRespondantName) ? "" : FormNRespondantName);
                aa.zapComplaintFormLastModifiedOn = LastModifiedOn;
            }
            else
            {
                aa.zapRelated_Complaint_ID = 0;
                aa.zapRelated_RegDiaryNumber = "";
                aa.zapComplainantRERAnumber = "";
                aa.zapComplainantName = "";
                aa.zapRespondantName = "";
            }
            return View("Display_ListEnclosuresDocFormN", aa);
        }

        //Lock-Unlock Handler (FormN Documents List)
        public JsonResult LockUnlockHandler_FormNcomplaintDocumentList(string parmComplaintID, string parmLockUnlock, string parmRelatedComplaintID)
        {
            Int32 retvalueLockUnlock = 0;
            Int32 retValue = 1;
            try
            {
                #region Parameters
                Int64 ComplaintCode = 0;
                Int64 RelatedComplaintCode = 0;
                Int32 IsDraftCode = 0;
                string userName = string.Empty;
                string userID = string.Empty;
                string RelatedRemarksIfAny = string.Empty;
                string RelatedLockUnlockMsg = string.Empty;

                if (parmComplaintID != string.Empty)
                {
                    ComplaintCode = Convert.ToInt64(parmComplaintID);
                }
                if (parmLockUnlock != string.Empty)
                {
                    IsDraftCode = Convert.ToInt32(parmLockUnlock);
                }
                if (parmRelatedComplaintID != string.Empty)
                {
                    RelatedComplaintCode = Convert.ToInt32(parmRelatedComplaintID);
                }
                userID = User.Identity.GetUserId();
                userName = User.Identity.GetUserName();
                RelatedRemarksIfAny = "FormN complaint document(s) list details";
                switch (IsDraftCode)
                {
                    case 1:
                        RelatedLockUnlockMsg = "Unlock request";
                        break;
                    case 5:
                        RelatedLockUnlockMsg = "Lock request";
                        break;
                    default:
                        RelatedLockUnlockMsg = "others";
                        break;
                }
                #endregion
                ClsMethod_ComplaintFormN_Documents sdb = new ClsMethod_ComplaintFormN_Documents();
                retvalueLockUnlock = sdb.Update_LockUnLockHandler_FormNcomplaint_DocumentsListDetails(ComplaintCode, RelatedComplaintCode, IsDraftCode, userName, userID, RelatedRemarksIfAny, RelatedLockUnlockMsg);
            }
            catch (Exception ex)
            {
                string retex = ex.ToString();
                retValue = 0;
            }

            Int32 IsDraft = retvalueLockUnlock; // 5;            
            Int32 parmStatusCode = 102;
            string parmStatus = "Request processed! Invalid.";
            if (retValue == 1)
            {
                if (IsDraft == 1)
                {
                    parmStatusCode = 101;
                    parmStatus = "Successfully locked complaint document(s) list details.";
                }
                else if (IsDraft == 5)
                {
                    parmStatusCode = 105;
                    parmStatus = "Successfully un-locked complaint document(s) list details.";
                }
                else if (IsDraft == 6)
                {
                    parmStatusCode = 106;
                    parmStatus = "Invalid lock-Unlock Action.";
                }
                else
                {
                    parmStatusCode = 100;
                    parmStatus = "Invalid lock-Unlock Action.";
                }
            }
            else
            {
                parmStatusCode = 102;
                parmStatus = "Request processed! Failed.";
            }

            return Json(new
            {
                statusCode = parmStatusCode,
                status = parmStatus,
                remarks = string.Empty
            }, JsonRequestBehavior.AllowGet);
        }

