        //Lock-Unlock Handler
        public JsonResult LockUnlockHandler_ComplaintFormNcontentDetails(string parmComplaintId, string parmLockUnlock, string parmComplaintIndexID)
        {
            Int32 retvalueLockUnlock = 0;
            Int32 retValue = 1;
            try
            {
                #region Parameters
                Int64 ComplaintCode = 0;
                Int64 IndexID = 0;
                Int32 IsDraftCode = 0;
                string userName = string.Empty;
                string userID = string.Empty;
                string RelatedRemarksIfAny = string.Empty;
                string RelatedLockUnlockMsg = string.Empty;

                if (parmComplaintId != string.Empty)
                {
                    ComplaintCode = Convert.ToInt64(parmComplaintId);
                }
                if (parmLockUnlock != string.Empty)
                {
                    IsDraftCode = Convert.ToInt32(parmLockUnlock);
                }
                if (parmComplaintIndexID != string.Empty)
                {
                    IndexID = Convert.ToInt32(parmComplaintIndexID);
                }
                userID = User.Identity.GetUserId();
                userName = User.Identity.GetUserName();
                RelatedRemarksIfAny = "Complaint Form-N details";
                switch (IsDraftCode)
                {
                    case 1:
                        RelatedLockUnlockMsg = "Unlock request";
                        break;
                    case 5:
                        RelatedLockUnlockMsg = "Lock request";
                        break;
                    default:
                        RelatedLockUnlockMsg = "others";
                        break;
                }
                #endregion
                ClsMethod_ComplaintFormN_Registration sdb = new ClsMethod_ComplaintFormN_Registration();
                retvalueLockUnlock = sdb.Update_LockUnLockHandler_FormNcomplaint_ContentDetails(ComplaintCode, IndexID, IsDraftCode, userName, userID, RelatedRemarksIfAny, RelatedLockUnlockMsg);
            }
            catch (Exception ex)
            {
                string retex = ex.ToString();
                retValue = 0;
            }

            Int32 IsDraft = retvalueLockUnlock; // 5;            
            Int32 parmStatusCode = 102;
            string parmStatus = "Request processed! Invalid.";
            if (retValue == 1)
            {
                if (IsDraft == 1)
                {
                    parmStatusCode = 101;
                    parmStatus = "Successfully locked complaint Form-N details.";
                }
                else if (IsDraft == 5)
                {
                    parmStatusCode = 105;
                    parmStatus = "Successfully un-locked complaint Form-N details.";
                }
                else if (IsDraft == 6)
                {
                    parmStatusCode = 106;
                    parmStatus = "Invalid lock-Unlock Action.";
                }
                else
                {
                    parmStatusCode = 100;
                    parmStatus = "Invalid lock-Unlock Action.";
                }
            }
            else
            {
                parmStatusCode = 102;
                parmStatus = "Request processed! Failed.";
            }

            return Json(new
            {
                statusCode = parmStatusCode,
                status = parmStatus,
                remarks = string.Empty
            }, JsonRequestBehavior.AllowGet);
        }

