                    FactsCaseCode = Convert.ToInt64(parmFactsCaseId);
                }
                userID = User.Identity.GetUserId();
                userName = User.Identity.GetUserName();
                RelatedRemarksIfAny = "Complaint Form-N (Facts of the Case)";
                switch (IsDraftCode)
                {
                    case 1:
                        RelatedLockUnlockMsg = "Unlock request";
                        break;
                    case 5:
                        RelatedLockUnlockMsg = "Lock request";
                        break;
                    default:
                        RelatedLockUnlockMsg = "others";
                        break;
                }
                #endregion
                ClsMethod_ComplaintFormN_Registration sdb = new ClsMethod_ComplaintFormN_Registration();
                retvalueLockUnlock = sdb.Update_LockUnLockHandler_FormNcomplaint_FactsOfTheCaseDetails(ComplaintCode, ProfileCode, FactsCaseCode, IsDraftCode, userName, userID, RelatedRemarksIfAny, RelatedLockUnlockMsg);
            }
            catch (Exception ex)
            {
                string retex = ex.ToString();
                retValue = 0;
            }

            Int32 IsDraft = retvalueLockUnlock; // 5;            
            Int32 parmStatusCode = 102;
            string parmStatus = "Request processed! Invalid.";
            if (retValue == 1)
            {
                if (IsDraft == 1)
                {
                    parmStatusCode = 101;
                    parmStatus = "Successfully locked complaint Form-N (Facts of the Case) details.";
                }
                else if (IsDraft == 5)
                {
                    parmStatusCode = 105;
                    parmStatus = "Successfully un-locked complaint Form-N (Facts of the Case) details.";
                }
                else if (IsDraft == 6)
                {
                    parmStatusCode = 106;
                    parmStatus = "Invalid lock-Unlock Action.";
                }
                else
                {
                    parmStatusCode = 100;
                    parmStatus = "Invalid lock-Unlock Action.";
                }
            }
            else
            {
                parmStatusCode = 102;
                parmStatus = "Request processed! Failed.";
            }

            return Json(new
            {
                statusCode = parmStatusCode,
                status = parmStatus,
                remarks = string.Empty
            }, JsonRequestBehavior.AllowGet);
        }
