                            FormM_RegDiaryNumber = (String.IsNullOrEmpty(FormMDiaryNumber) ? "" : FormMDiaryNumber);
                        }

                        sdb.Add_ComplaintFormM_PreHearingDate(smodel, userRole, pUser_WhoIdentified, ComplaintFormMID, FormM_RegDiaryNumber);
                        TempData["message"] = "Pre Hearing Details Added Successfully";
                        ModelState.Clear();
                    }
                    return RedirectToAction("FormM_PreHearingDateAdd");
                }
                catch (Exception ex)
                {
                    string exstr = ex.ToString();
                }
            }
            return View("FormM_PreHearingDateAdd", aa);
        }

