        // GET: IsDraftValue
        public Int32 Get_FormMCaseTransferDetails_Isdraftvalue_FromEventLog(Int64 ComplaintFormMNCode)
        {
            Int64 ComplaintFormMN = 0;
            ComplaintFormMN = ComplaintFormMNCode;

            ClsMethod_AuthDesk_FormM_CaseTransferDetails sdb = new ClsMethod_AuthDesk_FormM_CaseTransferDetails();

            Int32 returnIsdraftValue = 0;
            Int32 IsdraftValue = sdb.extractFormMCaseTransferDetails_Isdraftvalue_FromEventLog(ComplaintFormMN);
            //1-Lock, 2-Unlock, 9-Closed Transfer system
            if (IsdraftValue == 1 || IsdraftValue == 5 || IsdraftValue == 6)
            {
                returnIsdraftValue = 1;
            }
            else
            {
                returnIsdraftValue = IsdraftValue;
            }
            return returnIsdraftValue;
        }



