                    smodel.CreatedBy = pUser_WhoIdentified;
                    smodel.CreatedOn = DateTime.Now;
                    smodel.ComplaintType_MN = "FormM";
                    smodel.User_ID = userid;

                    if (string.IsNullOrEmpty(smodel.Dak_Number))
                    {
                        ModelState.Remove("Dak_Number");
                        smodel.Dak_Number = "";
                    }

                    if (!smodel.Dak_Date.HasValue)
                    {
                        ModelState.Remove("Dak_Date");
                        smodel.Dak_Date = DateTime.MinValue;
                    }
                    if (smodel.HardcopySetNumber == 0)
                    {
                        ModelState.Remove("HardcopySetNumber");
                        smodel.HardcopySetNumber = 0;
                    }
                    if (!smodel.F_column.HasValue)
                    {
                        smodel.F_column = DateTime.MinValue;
                        ModelState.Remove("F_column");
                    }

                    if (ModelState.IsValid)
                    {
                        if (Session["zapFormMDiaryNumber"] != null)
                        {
                            string FormMDiaryNumber = Session["zapFormMDiaryNumber"].ToString();
                            Int64? p_ID = Convert.ToInt64(Session["Profile_Id"]);
                            p_ID = (p_ID != null) ? Convert.ToInt64(p_ID) : 0;
                            smodel.InstitutionFormM_Code = FormMDiaryNumber;
                            smodel.Profile_ID = (p_ID != null) ? Convert.ToInt64(p_ID) : 0;

                            if (FormMDiaryNumber == smodel.Institution_Ref_Number)
                            {
                                smodel.IsSameDiaryNumberWithInstitutionNumber = 1;
                                //    smodel.IsLockRefNumber = 1;
                            }
                            //smodel.InstitutionFormM_ID = Convert.ToInt64(FormMDiaryNumber);
                        }
                        if (Session["ComplaintRegDiaryNumber_ID"] != null && Session["ComplaintRegDiaryNumber_NameYear"] != null)
                        {
                            Int64? diary_ID = Convert.ToInt64(Session["ComplaintRegDiaryNumber_ID"]);
                            Int64? diary_Year = Convert.ToInt64(Session["ComplaintRegDiaryNumber_NameYear"]);
                            diary_ID = (diary_ID != null) ? Convert.ToInt64(diary_ID) : 0;
                            diary_Year = (diary_Year != null) ? Convert.ToInt64(diary_Year) : 0;
                            smodel.Institution_Ref_Year = Convert.ToInt32(diary_Year);
                            smodel.Institution_Ref_ID = Convert.ToInt32(diary_ID);

                        }
                        sdb.Update_ComplaintFormM_Institution(smodel, userid, pUser_WhoIdentified);
                        TempData["message"] = "Pre Hearing Details updated Successfully";
                        ModelState.Clear();
                    }
                    return RedirectToAction("FormM_CaseAssignment");
                }
                catch (Exception ex)
                {
                    string exstr = ex.ToString();
                }
            }
            else
            {
                try
                {
                    smodel.ModifyBy = pUser_WhoIdentified;
                    smodel.ModifyOn = DateTime.Now;
                    smodel.CreatedBy = pUser_WhoIdentified;
                    smodel.CreatedOn = DateTime.Now;
                    smodel.ComplaintType_MN = "FormM";
                    smodel.User_ID = userid;

                    if (string.IsNullOrEmpty(smodel.Dak_Number))
                    {
                        ModelState.Remove("Dak_Number");
                        smodel.Dak_Number = "";
                    }

                    if (!smodel.Dak_Date.HasValue)
                    {
                        ModelState.Remove("Dak_Date");
                        smodel.Dak_Date = DateTime.MinValue;
                    }
                    if (smodel.HardcopySetNumber == 0)
                    {
                        ModelState.Remove("HardcopySetNumber");
                        smodel.HardcopySetNumber = 0;
                    }
                    if (!smodel.F_column.HasValue)
                    {
                        smodel.F_column = DateTime.MinValue;
                        ModelState.Remove("F_column");
                    }

                    if (!ModelState.IsValid)
                    {
                        var errors = ModelState
                                        .Where(x => x.Value.Errors.Count > 0).ToList();
                    }

                    if (ModelState.IsValid)
                    {
                        if (Session["zapFormMDiaryNumber"] != null)
                        {
                            string FormMDiaryNumber = Session["zapFormMDiaryNumber"].ToString();
                            smodel.InstitutionFormM_Code = FormMDiaryNumber;
                            Int64? p_ID = Convert.ToInt64(Session["Profile_Id"]);
                            p_ID = (p_ID != null) ? Convert.ToInt64(p_ID) : 0;
                            smodel.Profile_ID = (p_ID != null) ? Convert.ToInt64(p_ID) : 0;
                            if (FormMDiaryNumber == smodel.Institution_Ref_Number)
                            {
                                smodel.IsSameDiaryNumberWithInstitutionNumber = 1;
                                //    smodel.IsLockRefNumber = 1;
                            }
                            //smodel.InstitutionFormM_ID = Convert.ToInt64(FormMDiaryNumber);
                        }
                        if (Session["ComplaintRegDiaryNumber_ID"] != null && Session["ComplaintRegDiaryNumber_NameYear"] != null)
                        {
                            Int64? diary_ID = Convert.ToInt64(Session["ComplaintRegDiaryNumber_ID"]);
                            Int64? diary_Year = Convert.ToInt64(Session["ComplaintRegDiaryNumber_NameYear"]);
                            diary_ID = (diary_ID != null) ? Convert.ToInt64(diary_ID) : 0;
                            diary_Year = (diary_Year != null) ? Convert.ToInt64(diary_Year) : 0;

                            smodel.Institution_Ref_Year = Convert.ToInt32(diary_Year);
                            smodel.Institution_Ref_ID = Convert.ToInt32(diary_ID);
                        }

                        sdb.Add_ComplaintFormM_InstitutionData(smodel);
                        TempData["message"] = "Pre Hearing Details Added Successfully";
                        ModelState.Clear();
                    }
                    return RedirectToAction("FormM_CaseAssignment");
                }
                catch (Exception ex)
                {
                    string exstr = ex.ToString();
                }
            }
            return View("FormM_CaseAssignment", aa);
        }

        [HttpGet]
        public ActionResult Edit_FormM_InstitutionData(Int64 InstitutionFormM_ID)
        {
            ClsMethod_AuthDesk_FormM_PreHearingDate sdb = new ClsMethod_AuthDesk_FormM_PreHearingDate();
            Cls_Prp_FormM_CaseAssignment aa = new Cls_Prp_FormM_CaseAssignment();

            //ClsMethod_AuthDesk_PreHearingFixedForMaster objdis1 = new ClsMethod_AuthDesk_PreHearingFixedForMaster();
            ClsMethod_AuthDesk_PreHearingBenchMaster objdis2 = new ClsMethod_AuthDesk_PreHearingBenchMaster();

            string userRole = string.Empty;
            userRole = getUserRole();

            Int64 InstitutionFormMID = 0;

            InstitutionFormMID = InstitutionFormM_ID;

            //aa.PreHearingFixedForMaster = objdis1.Display_AuthDesk_Complaint_PreHearingDateFixedForMaster(userRole);
            aa.PreHearingBenchMaster = objdis2.Display_AuthDesk_Complaint_PreHearingFormMBenchMaster(userRole);
            aa.prpongoing = sdb.Display_AuthDesk_ComplaintFormM_InstitutionByID(InstitutionFormM_ID);

            foreach (var item in aa.prpongoing)
            {
                aa.InstitutionFormM_IndexID = item.InstitutionFormM_IndexID;
                aa.InstitutionFormM_ID = item.InstitutionFormM_ID;
                aa.InstitutionFormM_Code = item.InstitutionFormM_Code;
                aa.Profile_ID = item.Profile_ID;
                aa.User_ID = item.User_ID;
                aa.ComplaintType_MN = item.ComplaintType_MN;
                aa.IsSameDiaryNumberWithInstitutionNumber = item.IsSameDiaryNumberWithInstitutionNumber;

                // Institution Reference
                aa.Institution_Ref_ID = item.Institution_Ref_ID;
                aa.Institution_Ref_Year = item.Institution_Ref_Year;
                aa.Institution_Ref_Number = item.Institution_Ref_Number;
                aa.Institution_Ref_Date = item.Institution_Ref_Date ?? DateTime.MinValue;
                aa.IsManualAssignBench = item.IsManualAssignBench;
                aa.AssignementBench_ID = item.AssignementBench_ID;
                aa.AssignementBench_Name = item.AssignementBench_Name;
                aa.NatureOfComplaint_Statement = item.NatureOfComplaint_Statement;
                aa.NatureOfComplaint_Key1 = item.NatureOfComplaint_Key1;
                aa.NatureOfComplaint_Key2 = item.NatureOfComplaint_Key2;
                aa.NatureOfComplaint_Key3 = item.NatureOfComplaint_Key3;
                aa.ReliefSought_Statement = item.ReliefSought_Statement;
                aa.Dak_Number = item.Dak_Number;
                aa.Dak_Date = item.Dak_Date ?? DateTime.MinValue;
                aa.IsComplaintHardcopySetYesNo = item.IsComplaintHardcopySetYesNo;
                aa.HardcopySetNumber = item.HardcopySetNumber;
                aa.NumberOfComplainant = item.NumberOfComplainant;
                aa.NumberOfRespondent = item.NumberOfRespondent;
                aa.Remarks_IfAny = item.Remarks_IfAny;
                aa.A_column = item.A_column;
                aa.B_column = item.B_column;
                aa.C_column = item.C_column;
                aa.D_column = item.D_column;
                aa.E_column = item.E_column;
                aa.F_column = item.F_column ?? DateTime.MinValue;
                aa.IsActive = item.IsActive;
                aa.IsDraft = item.IsDraft;
                aa.IsLock = item.IsLock;
                aa.IsLockRefNumber = item.IsLockRefNumber;
                aa.IsPublicView = item.IsPublicView;
                aa.CreatedBy = item.CreatedBy;
                aa.CreatedOn = item.CreatedOn;
                aa.ModifyBy = item.ModifyBy;
                aa.ModifyOn = item.ModifyOn;
            }
            var onlineBench = new BenchMaster { onlineBench_ID = 205, onlineBenchName = "Online Hearing Bench (Default)" };
            aa.onlineBench_ID = onlineBench.onlineBench_ID;
            aa.onlineBenchName = onlineBench.onlineBenchName;

            if (aa.IsManualAssignBench == 0)
            {
                aa.PreHearingBenchMaster.Add(new ClsPrp_AuthDesk_PreHearingBench_Master
                {
                    PreHearingBench_ID = onlineBench.onlineBench_ID,
                    PreHearingBenchName = onlineBench.onlineBenchName
                });
            }
            if (Session["zapFormMDiaryNumber"] != null)
            {
                string FormMDiaryNumber = Session["zapFormMDiaryNumber"].ToString();
                string FormMComplainantName = Session["zapFormMComplainantName"].ToString();
                string FormMRespondantName = Session["zapFormMRespondantName"].ToString();
                string ComplainantRERAnumber = Session["zapComplainantRERAnumber"].ToString();
                Int64? zapComplaintFormM_ID = Convert.ToInt64(Session["zapComplaintFormM_ID"]);
                DateTime? LastModifiedOn = Convert.ToDateTime(Session["LastModifiedOn"]);

                aa.zapRelated_Complaint_ID = (zapComplaintFormM_ID != null) ? Convert.ToInt64(zapComplaintFormM_ID) : 0;
                aa.zapRelated_RegDiaryNumber = (String.IsNullOrEmpty(FormMDiaryNumber) ? "" : FormMDiaryNumber);
                aa.zapComplainantRERAnumber = (String.IsNullOrEmpty(ComplainantRERAnumber) ? "" : ComplainantRERAnumber);
                aa.zapComplainantName = (String.IsNullOrEmpty(FormMComplainantName) ? "" : FormMComplainantName);
                aa.zapRespondantName = (String.IsNullOrEmpty(FormMRespondantName) ? "" : FormMRespondantName);
                aa.zapComplaintFormLastModifiedOn = LastModifiedOn;
            }
            else
            {
                aa.zapRelated_Complaint_ID = 0;
                aa.zapRelated_RegDiaryNumber = "";
                aa.zapComplainantRERAnumber = "";
                aa.zapComplainantName = "";
                aa.zapRespondantName = "";
            }

            TempData["Institutionsubmitvalue"] = "Update"; TempData.Keep();
            return View("FormM_CaseAssignment", aa);
        }

