        [HttpGet]
        public ActionResult FormN_CaseAssignment()
        {
            ClsMethod_AuthDesk_FormM_PreHearingDate sdb = new ClsMethod_AuthDesk_FormM_PreHearingDate();
            Cls_Prp_FormN_CaseAssignment aa = new Cls_Prp_FormN_CaseAssignment();

            //ClsMethod_AuthDesk_PreHearingFixedForMaster objdis1 = new ClsMethod_AuthDesk_PreHearingFixedForMaster();
            ClsMethod_AuthDesk_FormM_PreHearingDate objdis2 = new ClsMethod_AuthDesk_FormM_PreHearingDate();

            string userRole = string.Empty;
            Int64 ComplaintFormMID = 0;
            userRole = getUserRole();
            ViewBag.UserRoleId = userRole;

            if (Session["zapFormNDiaryNumber"] != null)
            {
                Int64? ComplaintFormN_ID = Convert.ToInt64(Session["zapComplaintFormN_ID"]);
                ComplaintFormMID = (ComplaintFormN_ID != null) ? Convert.ToInt64(ComplaintFormN_ID) : 0;
            }
            if (Session["Profile_Id"] != null)
            {
                Int64? p_ID = Convert.ToInt64(Session["Profile_Id"]);
                p_ID = (p_ID != null) ? Convert.ToInt64(p_ID) : 0;
            }
            if (Session["ComplaintRegDiaryNumber_ID"] != null && Session["ComplaintRegDiaryNumber_NameYear"] != null)
            {
                Int64? diary_ID = Convert.ToInt64(Session["ComplaintRegDiaryNumber_ID"]);
                Int64? diary_Year = Convert.ToInt64(Session["ComplaintRegDiaryNumber_NameYear"]);
                diary_ID = (diary_ID != null) ? Convert.ToInt64(diary_ID) : 0;
                diary_Year = (diary_Year != null) ? Convert.ToInt64(diary_Year) : 0;
            }


            var staticBenchList = new List<BenchMasters>();
            staticBenchList.Add(new BenchMasters { onlineBench_ID = 101, onlineBenchName = "Judicial Bench 1" });
            staticBenchList.Add(new BenchMasters { onlineBench_ID = 205, onlineBenchName = "Judicial Bench 2(Default)" });
            staticBenchList.Add(new BenchMasters { onlineBench_ID = 310, onlineBenchName = "Judicial Bench 3" });
            staticBenchList.Add(new BenchMasters { onlineBench_ID = 450, onlineBenchName = "Judicial Bench 4" });
            aa.OnlineBenchMaster = staticBenchList;

            if (aa.OnlineBenchMaster != null && aa.OnlineBenchMaster.Count > 1)
            {
                var onlineBench = aa.OnlineBenchMaster[1];
                aa.onlineBench_ID = onlineBench.onlineBench_ID;
                aa.onlineBenchName = onlineBench.onlineBenchName;
            }

            //aa.PreHearingFixedForMaster = objdis1.Display_AuthDesk_Complaint_PreHearingDateFixedForMaster(userRole);
            aa.PreHearingBenchMaster = objdis2.Display_AuthDesk_Complaint_BenchMaster();
            aa.prpongoing = sdb.Display_AuthDesk_ComplaintFormN();

            if (Session["zapFormNDiaryNumber"] != null)
            {
                string FormMDiaryNumber = Session["zapFormNDiaryNumber"].ToString();
                string FormMComplainantName = Session["zapFormNComplainantName"].ToString();
                string FormMRespondantName = Session["zapFormNRespondantName"].ToString();
                string ComplainantRERAnumber = Session["zapComplainantRERAnumber"].ToString();
                Int64? ComplaintFormM_ID = Convert.ToInt64(Session["zapComplaintFormN_ID"]);
                DateTime? LastModifiedOn = Convert.ToDateTime(Session["LastModifiedOn"]);

                aa.zapRelated_Complaint_ID = (ComplaintFormM_ID != null) ? Convert.ToInt64(ComplaintFormM_ID) : 0;
                aa.zapRelated_RegDiaryNumber = (String.IsNullOrEmpty(FormMDiaryNumber) ? "" : FormMDiaryNumber);
                aa.zapComplainantRERAnumber = (String.IsNullOrEmpty(ComplainantRERAnumber) ? "" : ComplainantRERAnumber);
                aa.zapComplainantName = (String.IsNullOrEmpty(FormMComplainantName) ? "" : FormMComplainantName);
                aa.zapRespondantName = (String.IsNullOrEmpty(FormMRespondantName) ? "" : FormMRespondantName);
                aa.zapComplaintFormLastModifiedOn = LastModifiedOn;
                aa.Institution_Ref_Number = FormMDiaryNumber;
                aa.IsManualAssignBench = 1;
                aa.Institution_Ref_Date = DateTime.Now;
            }
            else
            {
                aa.zapRelated_Complaint_ID = 0;
                aa.zapRelated_RegDiaryNumber = "";
                aa.zapComplainantRERAnumber = "";
                aa.zapComplainantName = "";
                aa.zapRespondantName = "";
            }

            //Set Default Business On Date As Today
            //aa.D_column = DateTime.Now;

            TempData["Institutionsubmitvalue"] = "Save"; TempData.Keep();
            return View("FormN_CaseAssignment", aa);
        }

        [HttpPost]
        public ActionResult FormN_InstitutionDataAdd(Cls_Prp_FormN_CaseAssignment smodel)
        {
            string userRole = string.Empty;
            userRole = getUserRole();
            string pUser_WhoIdentified = User.Identity.Name;
            string userid = User.Identity.GetUserId();

            ClsMethod_AuthDesk_FormM_PreHearingDate sdb = new ClsMethod_AuthDesk_FormM_PreHearingDate();
            Cls_Prp_FormN_CaseAssignment aa = new Cls_Prp_FormN_CaseAssignment();

            // ClsMethod_AuthDesk_PreHearingFixedForMaster objmaster = new ClsMethod_AuthDesk_PreHearingFixedForMaster();
            ClsMethod_AuthDesk_PreHearingBenchMaster objmaster2 = new ClsMethod_AuthDesk_PreHearingBenchMaster();
            // aa.PreHearingFixedForMaster = objmaster.Display_AuthDesk_Complaint_PreHearingDateFixedForMaster(userRole);
            aa.PreHearingBenchMaster = objmaster2.Display_AuthDesk_Complaint_PreHearingFormMBenchMaster(userRole);

            bool isSectionComplete =
           !string.IsNullOrEmpty(smodel.Dak_Number) &&
           smodel.Dak_Date.HasValue &&
           smodel.HardcopySetNumber > 0 &&
           smodel.NumberOfComplainant > 0 &&
           smodel.NumberOfRespondent > 0;

            smodel.IsLock = isSectionComplete ? 1 : 0;


            //smodel.IsSameDiaryNumberWithInstitutionNumber = 1;



            if (TempData["Institutionsubmitvalue"].ToString() == "Update")
            {
                try
                {
                    smodel.ModifyBy = pUser_WhoIdentified;
                    smodel.ModifyOn = DateTime.Now;
                    smodel.CreatedBy = pUser_WhoIdentified;
                    smodel.CreatedOn = DateTime.Now;
                    smodel.ComplaintType_MN = "FormN";
                    smodel.User_ID = userid;

                    if (string.IsNullOrEmpty(smodel.Dak_Number))
                    {
                        ModelState.Remove("Dak_Number");
                        smodel.Dak_Number = "";
                    }

                    if (!smodel.Dak_Date.HasValue)
                    {
                        ModelState.Remove("Dak_Date");
                        smodel.Dak_Date = DateTime.MinValue;
                    }
                    if (smodel.HardcopySetNumber == 0)
                    {
                        ModelState.Remove("HardcopySetNumber");
                        smodel.HardcopySetNumber = 0;
                    }
                    if (!smodel.F_column.HasValue)
                    {
                        smodel.F_column = DateTime.MinValue;
                        ModelState.Remove("F_column");
                    }

                    if (ModelState.IsValid)
                    {
                        if (Session["zapFormNDiaryNumber"] != null)
                        {
                            string FormNDiaryNumber = Session["zapFormNDiaryNumber"].ToString();
                            Int64? p_ID = Convert.ToInt64(Session["Profile_Id"]);
                            p_ID = (p_ID != null) ? Convert.ToInt64(p_ID) : 0;
                            smodel.InstitutionFormN_Code = FormNDiaryNumber;
                            smodel.Profile_ID = (p_ID != null) ? Convert.ToInt64(p_ID) : 0;

                            if (FormNDiaryNumber == smodel.Institution_Ref_Number)
                            {
                                smodel.IsSameDiaryNumberWithInstitutionNumber = 1;
                                //    smodel.IsLockRefNumber = 1;
                            }
                            //smodel.InstitutionFormM_ID = Convert.ToInt64(FormMDiaryNumber);
                        }
                        if (Session["ComplaintRegDiaryNumber_ID"] != null && Session["ComplaintRegDiaryNumber_NameYear"] != null)
                        {
                            Int64? diary_ID = Convert.ToInt64(Session["ComplaintRegDiaryNumber_ID"]);
                            Int64? diary_Year = Convert.ToInt64(Session["ComplaintRegDiaryNumber_NameYear"]);
                            diary_ID = (diary_ID != null) ? Convert.ToInt64(diary_ID) : 0;
                            diary_Year = (diary_Year != null) ? Convert.ToInt64(diary_Year) : 0;
                            smodel.Institution_Ref_Year = Convert.ToInt32(diary_Year);
                            smodel.Institution_Ref_ID = Convert.ToInt32(diary_ID);

                        }
                        sdb.Update_ComplaintFormN_Institution(smodel, userid, pUser_WhoIdentified);
                        TempData["message"] = "Pre Hearing Details updated Successfully";
                        ModelState.Clear();
                    }
                    return RedirectToAction("FormN_CaseAssignment");
                }
                catch (Exception ex)
                {
                    string exstr = ex.ToString();
                }
            }
            else
            {
                try
                {
                    smodel.ModifyBy = pUser_WhoIdentified;
                    smodel.ModifyOn = DateTime.Now;
                    smodel.CreatedBy = pUser_WhoIdentified;
                    smodel.CreatedOn = DateTime.Now;
                    smodel.ComplaintType_MN = "FormN";
                    smodel.User_ID = userid;

                    if (string.IsNullOrEmpty(smodel.Dak_Number))
                    {
                        ModelState.Remove("Dak_Number");
                        smodel.Dak_Number = "";
                    }

                    if (!smodel.Dak_Date.HasValue)
                    {
                        ModelState.Remove("Dak_Date");
                        smodel.Dak_Date = DateTime.MinValue;
                    }
                    if (smodel.HardcopySetNumber == 0)
                    {
                        ModelState.Remove("HardcopySetNumber");
                        smodel.HardcopySetNumber = 0;
                    }
                    if (!smodel.F_column.HasValue)
                    {
                        smodel.F_column = DateTime.MinValue;
                        ModelState.Remove("F_column");
                    }

                    if (!ModelState.IsValid)
                    {
                        var errors = ModelState
                                        .Where(x => x.Value.Errors.Count > 0).ToList();
                    }

                    if (ModelState.IsValid)
                    {
                        if (Session["zapFormNDiaryNumber"] != null)
                        {
                            string FormNDiaryNumber = Session["zapFormNDiaryNumber"].ToString();
                            smodel.InstitutionFormN_Code = FormNDiaryNumber;
                            Int64? p_ID = Convert.ToInt64(Session["Profile_Id"]);
                            p_ID = (p_ID != null) ? Convert.ToInt64(p_ID) : 0;
                            smodel.Profile_ID = (p_ID != null) ? Convert.ToInt64(p_ID) : 0;
                            if (FormNDiaryNumber == smodel.Institution_Ref_Number)
                            {
                                smodel.IsSameDiaryNumberWithInstitutionNumber = 1;
                                //    smodel.IsLockRefNumber = 1;
                            }
                            //smodel.InstitutionFormM_ID = Convert.ToInt64(FormMDiaryNumber);
                        }
                        if (Session["ComplaintRegDiaryNumber_ID"] != null && Session["ComplaintRegDiaryNumber_NameYear"] != null)
                        {
                            Int64? diary_ID = Convert.ToInt64(Session["ComplaintRegDiaryNumber_ID"]);
                            Int64? diary_Year = Convert.ToInt64(Session["ComplaintRegDiaryNumber_NameYear"]);
                            diary_ID = (diary_ID != null) ? Convert.ToInt64(diary_ID) : 0;
                            diary_Year = (diary_Year != null) ? Convert.ToInt64(diary_Year) : 0;

                            smodel.Institution_Ref_Year = Convert.ToInt32(diary_Year);
                            smodel.Institution_Ref_ID = Convert.ToInt32(diary_ID);
                        }

                        sdb.Add_ComplaintFormN_InstitutionData(smodel);
                        TempData["message"] = "Pre Hearing Details Added Successfully";
                        ModelState.Clear();
                    }
                    return RedirectToAction("FormN_CaseAssignment");
                }
                catch (Exception ex)
                {
                    string exstr = ex.ToString();
                }
            }
            return View("FormN_CaseAssignment", aa);
        }

