        private bool SaveComplaintInterimOrdersFormM(ClsPrp_AuthDesk_FormM_PreHearingInterimOrder smodel, Int64 z_ComplaintFormM_ID, Int64 z_HearingFormM_ID, Int64 z_HearingIndexFormM_ID, String z_ComplaintFormDoc_FilePath, String z_ComplaintFormDoc_FileName, String z_ComplaintFormDoc_FileSize, String z_ComplaintFormDoc_FileFormat, Int32 z_ComplaintFormDoc_IsGroup, string z_FormM_DiaryNumber)
        {
            Int64 FormMN_ID = 0;
            Int64 HearingFormMN_ID = 0;
            Int64 HearingIndexFormMN_ID = 0;
            FormMN_ID = z_ComplaintFormM_ID;
            HearingFormMN_ID = z_HearingFormM_ID;
            HearingIndexFormMN_ID = z_HearingIndexFormM_ID;
            string FormMNDoc_FilePath = String.IsNullOrEmpty(z_ComplaintFormDoc_FilePath) ? string.Empty : z_ComplaintFormDoc_FilePath;
            string FormMNDoc_FileName = String.IsNullOrEmpty(z_ComplaintFormDoc_FileName) ? string.Empty : z_ComplaintFormDoc_FileName;
            string FormMNDoc_FileSize = String.IsNullOrEmpty(z_ComplaintFormDoc_FileSize) ? string.Empty : z_ComplaintFormDoc_FileSize;
            string FormMNDoc_FileFormat = String.IsNullOrEmpty(z_ComplaintFormDoc_FileFormat) ? string.Empty : z_ComplaintFormDoc_FileFormat;
            Int32 FormMNDoc_IsGroup = z_ComplaintFormDoc_IsGroup;
            string FormM_DiaryNumber = String.IsNullOrEmpty(z_FormM_DiaryNumber) ? string.Empty : z_FormM_DiaryNumber;

            string UID = User.Identity.GetUserId();
            string userName = User.Identity.Name;

            bool varRET = false;

            try
            {
                if (ModelState.IsValid)
                {
                    ClsMethod_AuthDesk_FormM_PreHearingIntrimOrder savedb = new ClsMethod_AuthDesk_FormM_PreHearingIntrimOrder();
                    if (savedb.Add_ComplaintInterimOrdersFormM_Documents(smodel, FormMN_ID, HearingFormMN_ID, HearingIndexFormMN_ID, FormMNDoc_FilePath, FormMNDoc_FileName, FormMNDoc_FileSize, FormMNDoc_FileFormat, FormMNDoc_IsGroup, UID, userName, FormM_DiaryNumber))
                    {
                        varRET = true;
                        ModelState.Clear();
                    }
                }
            }
            catch (Exception ex)
            {
                string varExMsg = ex.Message;
                varRET = false;
            }
            return varRET;
        }

