        public Int32 Get_FormNCaseTransferDetails_Isdraftvalue_FromEventLog(Int64 ComplaintFormMNCode)
        {
            Int64 ComplaintFormMN = 0;
            ComplaintFormMN = ComplaintFormMNCode;

