        [HttpPost]
        [ValidateAntiForgeryToken]
        public JsonResult FormN_OrderJudgmentDocumentUpload(HttpPostedFileBase uploadedFile, ClsPrp_AuthDesk_FormN_OrderJudgements smodel)
        {
            if (Request.Files.Count > 0 && (Request.Files[0].ContentLength != 0))
            {
                if (ModelState.IsValid)
                {
                    Clsprp_Master_Complaint_OrderJudgements clsprp = new Clsprp_Master_Complaint_OrderJudgements();
                    ClsMethod_Master_Complaint_OrderJudgements objdoc = new ClsMethod_Master_Complaint_OrderJudgements();
                    ClsPrp_AuthDesk_FormN_OrderJudgements clsprpOrderJudgement = new ClsPrp_AuthDesk_FormN_OrderJudgements();
                    ClsMethod_AuthDesk_FormN_ComplaintOrderJudgements objOrderJudgement = new ClsMethod_AuthDesk_FormN_ComplaintOrderJudgements();

                    //Transfer Case from N (Input form-N and Output form-N)
                    Int32 IndexId = 702;// smodel.ProjectDoc_InfoCode; (with ref to master table data)
                    Int32 TransferCaseFlag = smodel.oIsTransferCase;
                    string TransferCaseOption = smodel.oTransferTypeOption;
                    string ComplaintType = smodel.oRelated_ComplaintType_MN;

                    //Transfer Case from N to M (Input form-N and Output form-M)
                    if (TransferCaseFlag == 1)
                    {
                        if (TransferCaseOption == "TransferToAUTH")
                        {
                            //Input Form-N and Output Form-M
                            //(Transfer Case)('TransferToAUTH')
                            IndexId = 701;
                        }
                        else
                        {
                            //Input Form-N and Output Form-N
                            //(Transfer Case)('TransferToAO', 'TransferToOTH')
                            IndexId = 702;
                        }
                    }

                    Int64 ComplainantFormN_ID = 0;
                    Int64 FormN_TransferId = 0;
                    Int64 FormN_TransferIndexId = 0;
                    string ComplainantFormN_DiaryNumber = string.Empty;
                    if (Session["zapComplaintFormN_ID"] != null)
                    {
                        if (Session["zapComplaintFormN_ID"].ToString() != "0")
                        {
                            ComplainantFormN_ID = Convert.ToInt64(Session["zapComplaintFormN_ID"]);
                            ComplainantFormN_DiaryNumber = Convert.ToString(Session["zapFormNDiaryNumber"]);
                            Int64? TransferNId_ID = Convert.ToInt64(smodel.oRelated_CaseTransferN_ID);
                            Int64? TransferNIndexId_ID = Convert.ToInt64(smodel.oRelated_CaseTransferN_IndexID);
                            FormN_TransferId = (TransferNId_ID != null) ? Convert.ToInt64(TransferNId_ID) : 0;
                            FormN_TransferIndexId = (TransferNIndexId_ID != null) ? Convert.ToInt64(TransferNIndexId_ID) : 0;
                        }
                    }

                    #region Read Master Data By Document Type
                    clsprp.prpMasterOJdocs = objdoc.Display_Master_OrderJudgements_DocumentsByComplaintFormID(ComplainantFormN_ID);

                    Tuple<Int64, Int64, Int64, Int64> tupleSumCntFile = (objOrderJudgement.Display_ComplaintFormN_OrderJudgements_ByDocCodeInfo_ComplaintFormN_ID(ComplainantFormN_ID, ComplaintType, FormN_TransferId, TransferCaseFlag, TransferCaseOption, IndexId));
                    //Tuple Values(SumT, CntT, HearingSum, HearingCnt)

                    foreach (var item in clsprp.prpMasterOJdocs)
                    {
                        if (item.OrderJudgementDocMaster_InfoCode == IndexId)
                        {
                            clsprp.OrderJudgementDocMaster_IndexID = item.OrderJudgementDocMaster_IndexID;
                            clsprp.OrderJudgementDocMaster_InfoCode = item.OrderJudgementDocMaster_InfoCode;
                            clsprp.OrderJudgementDocMaster_InfoName = item.OrderJudgementDocMaster_InfoName;
                            clsprp.OrderJudgementDocMaster_RelatedSectionName = item.OrderJudgementDocMaster_RelatedSectionName;
                            clsprp.OrderJudgementDoc_SetFileSize = item.OrderJudgementDoc_SetFileSize;
                            clsprp.OrderJudgementDoc_SetFileFormat = item.OrderJudgementDoc_SetFileFormat;
                            clsprp.OrderJudgementDoc_SetFilePath = item.OrderJudgementDoc_SetFilePath;
                            clsprp.OrderJudgementDoc_ValidCode = item.OrderJudgementDoc_ValidCode;
                            clsprp.OrderJudgementDoc_ValidSubCode = item.OrderJudgementDoc_ValidSubCode;
                            clsprp.OrderJudgementDoc_ValidTinySubCode = item.OrderJudgementDoc_ValidTinySubCode;
                            clsprp.IsGroup = item.IsGroup;
                            clsprp.IsMandatory = item.IsMandatory;
                            clsprp.A_column = item.A_column;
                            clsprp.B_column = item.B_column;
                            clsprp.C_column = item.C_column;
                            clsprp.IsActive = item.IsActive;
                            clsprp.CreatedBy = item.CreatedBy;
                            clsprp.CreatedOn = item.CreatedOn;
                            clsprp.ModifyBy = item.ModifyBy;
                            clsprp.ModifyOn = item.ModifyOn;
                        }
                    }
                    #endregion

                    #region Declare Variables
                    var path = string.Empty;
                    var pathindb = string.Empty;
                    var savefileName = string.Empty;
                    string extensionPhotoIdentityDocument = string.Empty;
                    int byteCountPhotoIdentityDocument = 0;
                    string masterGetPhotoIdentityDocument = string.Empty;
                    Int32 extensionPutPhotoIdentityDocument = 0;
                    Int32 masterPutPhotoIdentityDocument = 0;
                    string masterPromoterDoc_SetFilePath = "rwdataOrdersJudgementsByAO";
                    bool IsValidFileType = false;
                    string pathprefixtype = "N";
                    #endregion

                    //Bad Request - No Doc
                    if (Request.Files.Count > 0)
                    {
                        var PhotoIdentityDocument = Request.Files[0];

                        //Bad Request - No Doc OR No Size
                        if (PhotoIdentityDocument != null && PhotoIdentityDocument.ContentLength > 0)
                        {
                            #region SaveFile Path Creation
                            if (clsprp.OrderJudgementDoc_SetFilePath.ToString() != string.Empty || clsprp.OrderJudgementDoc_SetFilePath.ToString() != null)
                            {
                                masterPromoterDoc_SetFilePath = clsprp.OrderJudgementDoc_SetFilePath.ToString();
                            }
                            pathindb = masterPromoterDoc_SetFilePath + "\\" + Convert.ToString(DateTime.Now.Year) + "\\" + Convert.ToString(pathprefixtype) + Convert.ToString(ComplainantFormN_ID) + "\\";
                            path = Server.MapPath("~/" + pathindb);

                            if (!Directory.Exists(path))
                            {
                                Directory.CreateDirectory(path);
                            }
                            #endregion

                            #region Master File Type Check
                            //Upload File Type
                            extensionPhotoIdentityDocument = Path.GetExtension(PhotoIdentityDocument.FileName);
                            switch (extensionPhotoIdentityDocument)
                            {
                                case ".JPEG":
                                case ".jpeg":
                                case ".JPG":
                                case ".jpg":
                                case ".PNG":
                                case ".png":
                                    {
                                        //Image Type
                                        extensionPutPhotoIdentityDocument = 102;
                                        break;
                                    }
                                case ".PDF":
                                case ".pdf":
                                    {
                                        //PDF Type
                                        extensionPutPhotoIdentityDocument = 103;
                                        break;
                                    }
                            }

                            //Master File Type
                            masterGetPhotoIdentityDocument = Convert.ToString(clsprp.OrderJudgementDoc_SetFileFormat);
                            switch (masterGetPhotoIdentityDocument)
                            {
                                case "JPEG/JPG/PDF":
                                    {
                                        //Both Image and PDF Type
                                        masterPutPhotoIdentityDocument = 101;
                                        break;
                                    }
                                case "JPEG/JPG":
                                case "JPEG":
                                case "JPG":
                                    {
                                        //Image Type
                                        masterPutPhotoIdentityDocument = 102;
                                        break;
                                    }
                                case "PDF":
                                    {
                                        //PDF Type
                                        masterPutPhotoIdentityDocument = 103;
                                        break;
                                    }
                            }
                            if (masterPutPhotoIdentityDocument == 101)
                            {
                                if (extensionPutPhotoIdentityDocument == 102 || extensionPutPhotoIdentityDocument == 103)
                                {
                                    IsValidFileType = true;
                                }
                            }
                            else
                            {
                                if (extensionPutPhotoIdentityDocument == masterPutPhotoIdentityDocument)
                                {
                                    IsValidFileType = true;
                                }
                            }
                            #endregion

                            //Check Number of Files Uploaded - Total for Particular Complaint 
                            if (tupleSumCntFile.Item2 < Convert.ToInt32(clsprp.IsGroup))
                            {
                                if (IsValidFileType)
                                {
                                    // Check Size of Files Uploaded - Total for Particular Complaint
                                    if (tupleSumCntFile.Item1 <= Convert.ToInt32(clsprp.OrderJudgementDoc_SetFileSize))
                                    {
                                        // Check Number of Files Uploaded - for Particular Hearing Date and should be less than TEN
                                        if (tupleSumCntFile.Item4 < Convert.ToInt32(10))
                                        {
                                            // Check Size of Files Uploaded - for Particular Hearing Date and should be less than 5MB
                                            if (tupleSumCntFile.Item3 <= Convert.ToInt32(5161920))
                                            {
                                                #region Save file to DB
                                                byteCountPhotoIdentityDocument = PhotoIdentityDocument.ContentLength;

                                                if (byteCountPhotoIdentityDocument <= Convert.ToInt32(clsprp.OrderJudgementDoc_SetFileSize))
                                                {
                                                    savefileName = RegexRemove(SaveFileDatePrefix() + Convert.ToString(clsprp.OrderJudgementDocMaster_InfoName) + Guid.NewGuid().ToString() + extensionPhotoIdentityDocument);
                                                    var pathsavefile = Path.Combine(path, savefileName);
                                                    PhotoIdentityDocument.SaveAs(pathsavefile);

                                                    var pathsavedb = Path.Combine(pathindb, savefileName);

                                                    Int64 inFormN_ID = ComplainantFormN_ID;
                                                    Int64 inIOTransferFormN_ID = FormN_TransferId;
                                                    string inFormDoc_FilePath = pathindb;
                                                    string inFormDoc_FileName = savefileName;
                                                    string inFormDoc_FileSize = Convert.ToString(byteCountPhotoIdentityDocument);
                                                    string inFormDoc_FileFormat = extensionPhotoIdentityDocument;

                                                    bool varRet = SaveOrderJudgmentDocumentFormNandTransNM(smodel, inFormN_ID, inIOTransferFormN_ID, inFormDoc_FilePath, inFormDoc_FileName, inFormDoc_FileSize, inFormDoc_FileFormat);
                                                    if (varRet != false)
                                                    {
                                                        return Json(new
                                                        {
                                                            //Data = "Complete",
                                                            statusCode = 101,
                                                            status = "Complete",
                                                            remarks = "Successfully uplaoded"
                                                        }, JsonRequestBehavior.AllowGet);
                                                    }
                                                    else
                                                    {
                                                        return Json(new
                                                        {
                                                            //Data = "Bad Request! Upload Failed",
                                                            statusCode = 105,
                                                            status = "Bad Request! Upload Failed",
                                                            remarks = "Not Saved! Upload Failed "
                                                        }, JsonRequestBehavior.AllowGet);
                                                    }
                                                }
                                                else
                                                {
                                                    decimal varSetFileSize = 0;
                                                    string varOutSetFileSize = string.Empty;
                                                    varSetFileSize = Convert.ToInt32(clsprp.OrderJudgementDoc_SetFileSize);

                                                    if (varSetFileSize > 1048576)
                                                    {
                                                        varOutSetFileSize = Math.Round(varSetFileSize * 100 / 1048576) / 100 + " MB";
                                                    }
                                                    else if (varSetFileSize > 1024)
                                                    {
                                                        varOutSetFileSize = Math.Round(varSetFileSize * 100 / 1024) / 100 + " KB";
                                                    }
                                                    else
                                                    {
                                                        varOutSetFileSize = varSetFileSize + " Bytes";
                                                    }

                                                    return Json(new
                                                    {
                                                        //Data = "Size less, File Name: " + uploadedFile.FileName,
                                                        statusCode = 103,
                                                        status = "File size should be less than " + varOutSetFileSize,
                                                        remarks = uploadedFile.FileName
                                                    }, JsonRequestBehavior.AllowGet);
                                                }
                                                #endregion
                                            }
                                            else
                                            {
                                                decimal varSetGroupFileSize = 0;
                                                string varOutSetGroupFileSize = string.Empty;

                                                varSetGroupFileSize = Convert.ToInt64(tupleSumCntFile.Item3);

                                                if (varSetGroupFileSize > 1048576)
                                                {
                                                    varOutSetGroupFileSize = Math.Round(varSetGroupFileSize * 100 / 1048576) / 100 + " MB";
                                                }
                                                else if (varSetGroupFileSize > 1024)
                                                {
                                                    varOutSetGroupFileSize = Math.Round(varSetGroupFileSize * 100 / 1024) / 100 + " KB";
                                                }
                                                else
                                                {
                                                    varOutSetGroupFileSize = varSetGroupFileSize + " Bytes";
                                                }


                                                return Json(new
                                                {
                                                    //Data = "Size less, File Name: " + uploadedFile.FileName,
                                                    statusCode = 107,
                                                    status = "Maximum number of uploaded files size limit reached.(Max:" + varOutSetGroupFileSize + ")",
                                                    remarks = uploadedFile.FileName
                                                }, JsonRequestBehavior.AllowGet);
                                            }
                                        }
                                        else
                                        {
                                            return Json(new
                                            {
                                                //Data = "Invalid Maximum number of uploaed files limit, File Name: " + uploadedFile.FileName,
                                                statusCode = 106,
                                                status = "Maximum number of uploaded files limit reached. (Maximum " + Convert.ToString("ten") + " files.)",
                                                remarks = uploadedFile.FileName
                                            }, JsonRequestBehavior.AllowGet);
                                        }
                                    }
                                    else
                                    {
                                        decimal varSetGroupFileSize = 0;
                                        string varOutSetGroupFileSize = string.Empty;

                                        varSetGroupFileSize = Convert.ToInt64(tupleSumCntFile.Item1);

                                        if (varSetGroupFileSize > 1048576)
                                        {
                                            varOutSetGroupFileSize = Math.Round(varSetGroupFileSize * 100 / 1048576) / 100 + " MB";
                                        }
                                        else if (varSetGroupFileSize > 1024)
                                        {
                                            varOutSetGroupFileSize = Math.Round(varSetGroupFileSize * 100 / 1024) / 100 + " KB";
                                        }
                                        else
                                        {
                                            varOutSetGroupFileSize = varSetGroupFileSize + " Bytes";
                                        }


                                        return Json(new
                                        {
                                            //Data = "Size less, File Name: " + uploadedFile.FileName,
                                            statusCode = 107,
                                            status = "Maximum number of uploaded files size limit reached.(Max:" + varOutSetGroupFileSize + ")",
                                            remarks = uploadedFile.FileName
                                        }, JsonRequestBehavior.AllowGet);
                                    }
                                }
                                else
                                {
                                    return Json(new
                                    {
                                        //Data = "Format not match, File Name: " + uploadedFile.FileName,
                                        statusCode = 104,
                                        status = "File format not matched.",
                                        remarks = uploadedFile.FileName
                                    }, JsonRequestBehavior.AllowGet);
                                }
                            }
                            else
                            {
                                return Json(new
                                {
                                    //Data = "Invalid Maximum number of uploaed files limit, File Name: " + uploadedFile.FileName,
                                    statusCode = 106,
                                    status = "Maximum number of uploaded files limit reached. (Maximum " + Convert.ToString(clsprp.IsGroup) + " files.)",
                                    remarks = uploadedFile.FileName
                                }, JsonRequestBehavior.AllowGet);
                            }
                        }
                        else
                        {
                            return Json(new
                            {
                                //Data = "Bad Request! Upload Failed",
                                statusCode = 102,
                                status = "Bad Request! Upload Failed",
                                remarks = string.Empty
                            }, JsonRequestBehavior.AllowGet);
                        }
                    }
                    else
                    {
                        return Json(new
                        {
                            //Data = "Bad Request! Upload Failed",
                            statusCode = 102,
                            status = "Bad Request! Upload Failed",
                            remarks = string.Empty
                        }, JsonRequestBehavior.AllowGet);
                    }
                }
                else
                {
                    return Json(new
                    {
                        //Data = "Bad Request! Upload Failed",
                        statusCode = 102,
                        status = "Mandatory field(s) required! Upload Failed",
                        remarks = string.Empty
                    }, JsonRequestBehavior.AllowGet);
                }
            }
            else
            {
                return Json(new
                {
                    //Data = "Bad Request! Upload Failed",
                    statusCode = 102,
                    status = "Bad Request! Upload Failed",
                    remarks = string.Empty
                }, JsonRequestBehavior.AllowGet);
            }
        }

        private bool SaveOrderJudgmentDocumentFormNandTransNM(ClsPrp_AuthDesk_FormN_OrderJudgements smodel, Int64 z_ComplaintFormN_ID, Int64 z_TransferFormN_ID, String z_ComplaintFormDoc_FilePath, String z_ComplaintFormDoc_FileName, String z_ComplaintFormDoc_FileSize, String z_ComplaintFormDoc_FileFormat)
        {
            Int64 FormNM_ID = 0;
            Int64 TransferFormNM_ID = 0;
            FormNM_ID = z_ComplaintFormN_ID;
            TransferFormNM_ID = z_TransferFormN_ID;
            string FormNMDoc_FilePath = String.IsNullOrEmpty(z_ComplaintFormDoc_FilePath) ? string.Empty : z_ComplaintFormDoc_FilePath;
            string FormNMDoc_FileName = String.IsNullOrEmpty(z_ComplaintFormDoc_FileName) ? string.Empty : z_ComplaintFormDoc_FileName;
            string FormNMDoc_FileSize = String.IsNullOrEmpty(z_ComplaintFormDoc_FileSize) ? string.Empty : z_ComplaintFormDoc_FileSize;
            string FormNMDoc_FileFormat = String.IsNullOrEmpty(z_ComplaintFormDoc_FileFormat) ? string.Empty : z_ComplaintFormDoc_FileFormat;

            string UID = User.Identity.GetUserId();
            string userName = User.Identity.Name;

            bool varRET = false;

            try
            {
                if (ModelState.IsValid)
                {
                    ClsMethod_AuthDesk_FormN_ComplaintOrderJudgements savedb = new ClsMethod_AuthDesk_FormN_ComplaintOrderJudgements();
                    if (savedb.Add_ComplaintOrderJudgementsFormN_Documents(smodel, FormNM_ID, TransferFormNM_ID, FormNMDoc_FilePath, FormNMDoc_FileName, FormNMDoc_FileSize, FormNMDoc_FileFormat, UID, userName))
                    {
                        varRET = true;
                        ModelState.Clear();
                    }
                }
            }
            catch (Exception ex)
            {
                string varExMsg = ex.Message;
                varRET = false;
            }
            return varRET;
        }

