                strBody += aa.Respondent_Name.ToString() + ",";
                strBody += "<br />";
                strBody += aa.ServiceNoticesRespondent_AddressLine1.ToString() + " " + aa.ServiceNoticesRespondent_AddressLine2.ToString() + ",";
                strBody += "<br />";
                strBody += aa.ServiceNoticesRespondent_AddressDistrictCodeName.ToString() + ", " + aa.ServiceNoticesRespondent_AddressStateCodeName.ToString() + " - " + aa.ServiceNoticesRespondent_AddressPIN.ToString();
                strBody += "<br /><br /><br />";
                strBody += "<p style='text-align:justify;'> Subject: - Notice under section 31 of Real Estate (Regulation and Development) Act, 2016 read with rule 36 (2) of Punjab State Real Estate (Regulation and Development) Rules, 2017.</p>";
                strBody += "<p style='text-align:justify;'> Whereas <b>Complaint No. - " + aa.ComplainantApplicant_RelatedComplaint_Code.ToString() + "</b> against you has been received with the Authority from the complainant(s) " + aa.Complainant_Name.ToString() + " (copy enclosed herewith alongwith requisite documents). The complainant has alleged contraventions by you of various Sections/Rules of the Real Estate (Regulation and Development) Act, 2016 and Punjab State Real Estate (Regulation and Development) Rules, 2017.</p>";
                strBody += "<p style='text-align:justify;'> By way of this notice, you are hereby, directed to appear in person or through your authorized representative before <b>" + aa.B_column.ToString() + ", the Real Estate Regulatory Authority, Punjab</b> situated at First Floor, Block-B, Plot Number-3, (Near Govt. Press UT), Madhya Marg, Sector-18A, Chandigarh, on <b>" + strHearingDate + " at " + aa.PreHearingTime.ToString() + "</b>, to answer the alleged contraventions as mentioned above.</p>";
                strBody += "<p style='text-align:justify;'> Further as per directions, you are required to file a reply to the complaint within <b>" + aa.C_column.ToString() + " days</b> of the receipt of this mail and a copy of the same be supplied to complainant two days in advance by way of Registered post/Speed post or reputed Courier by that date. Hence fail not.</p>";
                strBody += "<p style='text-align:justify;'> It is made clear that in case of your failure to attend the proceedings on the above mentioned fixed date, the matter will be decided in your absence and in accordance with law.</p>";
                strBody += "<br />";
                strBody += "Please view enclosed requisite documents herewith by clicking <a href='" + callbackUrl + "'>here (View Form and Documents (Link))</a>";
                strBody += "<br />";
                strBody += "Issued on this " + DateTime.Now.ToString("dd/MMM/yyyy");
                strBody += "<br /><br />";
                strBody += "<b>Authorized Signatory</b>";
                strBody += "<br />";
                strBody += "<b>Real Estate Regulatory Authority, Punjab</b>";
                strBody += "<br /><br />";
                strBody += "<b>Punjab RERA web portal</b>";
                strBody += "<br />";

                objRet.Body = strBody;
            }
            catch (Exception ex)
            {
                objRet.Destination = string.Empty;
                objRet.Subject = string.Empty;
                objRet.Body = ex.ToString();
            }
            return objRet;
        }
